const CACHE='fourth-dimension-v5';
const CORE=['./','./index.html','./styles.css','./app.js','./service.html','./service.css','./service.js','./tools/','./tools/index.html','./tools/tools.css','./tools/tools.js','./articles/','./news/','./projects/','./tutorials/','./archive.css','./archive.js','./content-data.js','./assets/logo.webp','./assets/hero-poster.jpg','./assets/app-icon-192.png','./assets/app-icon-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>Promise.allSettled(CORE.map(url=>cache.add(url)))).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;event.respondWith(fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response}).catch(async()=>{const hit=await caches.match(event.request);if(hit)return hit;const path=new URL(event.request.url).pathname;if(path.endsWith('/service.html'))return caches.match('./service.html');if(path.includes('/tools/'))return caches.match('./tools/index.html');for(const section of ['articles','news','projects','tutorials'])if(path.includes('/'+section+'/'))return caches.match('./'+section+'/');return caches.match('./index.html')}))});
